"""Browser acceptance for the offline report generated by the public bundle API."""

from __future__ import annotations

import argparse
import hashlib
import json
import tempfile
from pathlib import Path
from urllib.parse import urlsplit

from playwright.sync_api import expect, sync_playwright
from trainlab.diagnostic_bundle import STATUSES, create, verify


def make_bundle(root):
    findings = []
    for status in STATUSES:
        evidence, reviews = None, []
        if status not in ("NOT_RUN", "UNSUPPORTED"):
            path = root / f"{status}.json"
            raw = json.dumps({"status": status, "note": "public constructed control"}).encode()
            path.write_bytes(raw)
            pin = hashlib.sha256(raw).hexdigest()
            evidence = {"path": path.name, "sha256": pin, "pointer": []}
            reviews = [
                {
                    "reviewer": "Fixture reviewer",
                    "note": "Reviewed this report.",
                    "report_sha256": pin,
                }
            ]
        findings.append(
            {
                "id": "long-unbroken-identifier-" + "x" * 128 if status == "FAILED" else status,
                "pack_id": "coverage",
                "kind": "observation",
                "summary": "<b>Literal evidence</b>",
                "status": status,
                "evidence": evidence,
                "reviews": reviews,
            }
        )
    spec = {
        "schema": "trainlab.diagnostic-bundle-spec.v1",
        "title": "Veritas diagnostic browser acceptance",
        "data_classification": "CONSTRUCTED_PUBLIC",
        "packs": [
            {
                "id": "coverage",
                "version": "1",
                "applicability": "constructed browser control",
                "dependencies": [],
                "cost": "local file viewing",
                "evidence_requirements": [],
                "limitations": ["Constructed acceptance only."],
            }
        ],
        "findings": findings,
    }
    raw = json.dumps(spec).encode()
    spec_path = root / "spec.json"
    spec_path.write_bytes(raw)
    bundle = root / "bundle"
    pin = create(spec_path, hashlib.sha256(raw).hexdigest(), bundle)
    if not verify(bundle, pin)["valid"]:
        raise RuntimeError("Browser fixture did not verify")
    return bundle


def run(root, evidence):
    bundle = make_bundle(root)
    url = (bundle / "index.html").as_uri()
    with sync_playwright() as playwright:
        browser = playwright.chromium.launch(headless=True)
        try:
            context = browser.new_context(offline=True, viewport={"width": 1440, "height": 900})
            requests, errors = [], []
            context.on("request", lambda request: requests.append(request.url))
            page = context.new_page()
            page.on("pageerror", lambda error: errors.append(str(error)))
            page.goto(url)
            expect(page.get_by_role("heading", level=1)).to_have_text(
                "Veritas diagnostic browser acceptance"
            )
            picker = page.get_by_label("Filter findings", exact=True)
            cards = page.locator("article:visible")
            expect(cards).to_have_count(len(STATUSES))
            for status in STATUSES:
                picker.select_option(status)
                expect(cards).to_have_count(1)
                expect(cards.first).to_have_attribute("data-status", status)
                expect(
                    cards.first.get_by_text("<b>Literal evidence</b>", exact=True)
                ).to_be_visible()
            picker.select_option("ALL")
            expect(cards).to_have_count(len(STATUSES))
            page.screenshot(path=evidence / "desktop.png", full_page=True)
            picker.select_option("FAILED")
            picker.focus()
            page.keyboard.press("Tab")
            summary = cards.first.locator("summary")
            expect(summary).to_be_focused()
            page.keyboard.press("Enter")
            expect(cards.first.get_by_text("Reviewed this report.", exact=False)).to_be_visible()
            raw = cards.first.get_by_role("link", name="Raw JSON evidence")
            expect(raw).to_be_visible()
            page.set_viewport_size({"width": 320, "height": 740})
            if not page.evaluate("document.documentElement.scrollWidth === innerWidth"):
                raise RuntimeError("Diagnostic browser overflows its 320px viewport")
            page.screenshot(path=evidence / "mobile.png", full_page=True)
            raw_path = raw.get_attribute("href")
            raw.click()
            expect(page).to_have_url((bundle / raw_path).as_uri())
            saved_report = json.loads(page.locator("body").inner_text())
            if saved_report["status"] != "FAILED":
                raise RuntimeError("Raw evidence navigation opened the wrong report")
            external = [request for request in requests if urlsplit(request).scheme != "file"]
            if errors or external:
                raise RuntimeError(f"Browser errors or external requests: {errors}, {external}")
        finally:
            browser.close()
    print(
        "PASS: status filters, keyboard inspection, raw JSON, 320px layout, offline"
    )


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--evidence", type=Path, required=True)
    args = parser.parse_args()
    args.evidence.mkdir(parents=True, exist_ok=False)
    with tempfile.TemporaryDirectory(prefix="trainlab-diagnostic-browser-") as temp:
        run(Path(temp), args.evidence)
